exec(open(__file__.replace('homological-final.py','repair.py')).read().split("step('lem-cm-lattice")[0])
id='lem-truncated-homological-equation-with-conservative-loss'
replace(id,'- **(G) general case:** $h=0$;',r'- **(G) general case:** $h=0$, with the following parameter-free convention local to this item: for each fixed $\nu\in\Omega_{\alpha,\tau}$, $v(\cdot,\cdot,\nu)$ is holomorphic on $B_r\times S_s$, with angular mean zero and a uniform bound $N$ over the label family. Here the phase domain is $B_r\times S_s$ at that fixed real label; no holomorphy in a nonopen real parameter set is asserted;')
replace(id,'every $\\nu\\in O_h(\\Omega_{\\alpha,\\tau})$\nand every $k$',r'every parameter in the specified case (real $\nu\in\Omega_{\alpha,\tau}$ in (G), complex $\nu\in O_h(\Omega_{\alpha,\tau})$ in (T)) and every $k$')
replace(id,r'$$u(I,\vartheta,\nu):=\sum_{k\in\mathbb Z^n,\,k\ne0} \frac{v_k(I,\nu)}{i\,k\cdot\nu}\,e^{ik\cdot\vartheta}$$',r'$$u(I,\vartheta,\nu):=\sum_{k\in\mathbb Z^n,\,k\ne0} a_k(I,\nu)\,e^{ik\cdot\vartheta},\qquad a_k:=\frac{v_k}{i\,k\cdot\nu}\ \text{in (G) or when }0<|k|_1\le K\text{ in (T)},$$'+'\n   '+r'and set $a_k:=0$ when $|k|_1>K$ in (T). Thus no zero numerator is divided by a possibly zero discarded divisor.')
replace(id,'its sum $u$ is holomorphic there with',r'its sum $u$ is holomorphic in the phase variables in (G) and jointly holomorphic in all variables in (T), with')
step(id,'1.1',r'*Small divisors.* In (G), the fixed real parameter belongs to $\Omega_{\alpha,\tau}$, so $|k\cdot\nu|\ge\alpha|k|_1^{-\tau}$ for every nonzero mode, without a cutoff restriction. In (T), fix $\nu\in O_h(\Omega_{\alpha,\tau})$ and $0<|k|_1\le K$. There is a real label $\nu_0$ with $|\nu-\nu_0|_\infty<h$. Thus $|k\cdot\nu|\ge\alpha|k|_1^{-\tau}-|k|_1h\ge(\alpha/2)|k|_1^{-\tau}$, since $h|k|_1^{\tau+1}\le hK^{\tau+1}\le\alpha/2$. Only these retained modes are divided by their divisors; all other coefficients in (T) are defined as zero. [given, F1, algebra]')
step(id,'4.1',r'*Uniqueness.* In (G), comparing Fourier coefficients of any zero-mean phase-holomorphic solution at the fixed Diophantine label gives $(ik\cdot\nu)w_k=v_k$ for every nonzero mode; all divisors are nonzero, so its coefficients equal those of $u$. In (T), the same comparison holds on an open complex parameter domain. Retained-mode coefficients equal $a_k$ by step 1.1. For a discarded mode, $v_k=0$ and $(k\cdot\nu)w_k=0$; off the complex hyperplane $k\cdot\nu=0$, the coefficient is zero. Its continuity in the parameter extends that value across the hyperplane, since the complement of a nontrivial linear hyperplane is dense in every open ball. The coefficient $w_0$ is zero by the zero-mean assumption. Thus all coefficients agree in either case, and the Fourier representation in [F2] gives equality of the solutions on their common domain. [step 1.1, step 2.1, step 3.1, F2, algebra]')
